from lib import *
P('chu-pa', 'Chư Pa'); P('co-ca-va', 'Cô Ca Va'); P('dong-du', 'Đồng Dù'); P('binh-phu-ben-tre', 'Bình Phú, Bến Tre')
P('bau-coi', 'Bầu Cối'); P('tra-cao', 'Trà Cao'); P('dong-pan', 'Đồng Pan'); P('tam-binh-dist','x') if False else None
P('hon-quan', 'Hớn Quản'); P('suoi-tam-bung', 'Suối Tầm Bung'); P('rung-sat', 'Rừng Sác'); P('long-thanh', 'Long Thành')
P('tam-tanh', 'Tam Tanh'); P('son-tra', 'Sơn Trà'); P('camp-e-sepic', 'Camp Ê-sê-pích', in_='rvn') if False else None
P('long-tau-river', 'Lòng Tàu River'); P('chi-nh','x') if False else None
D = 'vietnam-hanoi'; OP = ['vietnam-operations']
E('chupa', '1969-01-10', 'Jan. 10', 'Chư Pa, Gia Lai, in the Highlands. Three battalions of the Saigon 42d Regiment, one of the 47th Regiment, 23d Division, and two Ranger battalions, with artillery, aircraft and some American infantry, open Bình Tây 48 against the base, 38 km northwest of Pleiku. The Highlands forces, forewarned, hit the landing; Bình Tây 49 is caught in an ambush, Bình Tây 50 from Phú Yên beaten in its turn. Twenty days: 2,500 out of action.', '98–100', also=OP, place='chu-pa', us=True, check='the end of the fighting; the history gives 20 days and its own figures.')
E('dewey', '1969-01-24', 'Jan. 24', 'Cô Ca Va, west of Trị–Thiên. The 9th Marines, 3d Marine Division, and five battalions of the Saigon 1st Division, some 7,000 men with air and artillery, open Dewey Canyon against the Route 559 depots and roads. The 5th Regiment, the 3d Sapper Battalion, the way stations and the western guerrillas hold them. After 18 days: 2,863 out of action, 49 aircraft shot down or destroyed, six guns.', '100–101', also=OP, place='co-ca-va', us=True, check='the end of the fighting and the figures; the history gives 18 days.')
E('paris-0125', '1969-01-25', 'Jan. 25', 'Paris. The first plenary session of the four-party conference opens: the DRV, the Front, the United States, Saigon. Xuân Thủy heads the DRV, Lê Đức Thọ special adviser; Trần Bửu Kiếm the Front, Nguyễn Thị Bình and Trần Hoài Nam deputies; Nguyễn Cao Kỳ Saigon, Phan Đăng Lâm deputy.', '101–2 and n. 1', th='vietnam-paris', also=[D], place='paris', polity='drv', us=True, see='cal.1969-01-18.vietnam-paris', ntags=['name:xuan-thuy','name:le-duc-tho','name:nguyen-thi-binh','name:nguyen-cao-ky','name:tran-buu-kiem'], names=['Xuân Thủy','Lê Đức Thọ','Nguyễn Thị Bình','Nguyễn Cao Kỳ','Trần Bửu Kiếm','Trần Hoài Nam','Phan Đăng Lâm'], check='the history says the United States was admitted to treat the Front as an official and lawful party; its note names Harriman at the head of the American side, where Lodge had been named Jan. 5 (see [[cal.1969-01-05.vietnam]]).')
E('mytho-0222', '1969-02-22', 'Feb. 22', 'Mỹ Tho and Đồng Tâm. At night Regiment 1, with Artillery Battalion 309F, raids the town and the base: dozens of Saigon and American troops out of action, 12 aircraft and six guns destroyed or damaged.', '111', also=OP, place='my-tho', us=True, bnd='night', see='cal.1969-02-22.vietnam-hanoi', words='"đêm 22-2-1969" (the night of Feb. 22, 1969).', check='the regiment\'s region; the history says Regiment 1 of the delta forces and does not number it.', lw='Mỹ Tho and Đồng Tâm raided by Regiment 1')
E('dongdu', '1969-02-26', 'Feb. 26', 'Đồng Dù, Củ Chi, the base of the American 25th Division. At 2:30 a.m. Battalion 3 of the Miền command\'s sappers and Battalion 28 of the 7th Division\'s, under Nguyễn Cụ, deputy chief of the Miền\'s sappers, cut seven wire fences and attack. In 30 minutes the division headquarters, signal area, radar, two artillery positions, 100 bunkers and 29 shelters are destroyed. Over 1,200 out of action, 179 vehicles, 12 guns and dozens of aircraft destroyed or damaged.', '107–8', also=OP, place='dong-du', us=True, t='02:30', see='cal.1969-02-22.vietnam-hanoi', words='"Hai giờ 30 phút ngày 26-2-1969" (2:30, Feb. 26, 1969).', check='the figures; the history gives its own. Nguyễn Cụ, called Nguyễn Tư Cường, has no name entry.')
E('benbinh', '1969-02-24', 'Feb. 24', 'Bình Phú, on the edge of Bến Tre town. At night a sapper company of the Bến Tre provincial command, with an inside agent, raids the base of the 2d Battalion, 10th Regiment, Saigon army: 120 out of action. Another company destroys five American 105 mm guns at Đồng Cò and Chợ Giữa. The secret cells then lead villagers of the town\'s edge to rise and break some strategic hamlets.', '111', place='binh-phu-ben-tre', bnd='night', words='"Đêm 24-2-1969" (the night of Feb. 24, 1969).', see='cal.1969-02-22.vietnam-hanoi', lw='Bình Phú, Bến Tre: sapper company raids a Saigon battalion')
E('feb-biendoa', '1969-02', 'Feb.', 'Eastern Nam Bộ. The 5th Division and local forces strike repeatedly around Biên Hòa and Long Bình; Regiment 33 hits a Royal Thai battalion at Bầu Cối, southeast of the Long Bình district post. Six battalions of the Saigon strategic reserve move to relieve the inner ring, and the 3d Airmobile Cavalry Brigade to hold the outer.', '108', also=OP, place='bau-coi', us=False, check='the days; the history gives only the month.', tags=['polity:thailand'], lw='Biên Hòa and Long Bình: the 5th Division; Bầu Cối')
E('feb-delta', '1969-02', 'Feb.', 'The Mekong Delta. Artillery raids on airfields and depots; Regiment 2, less Battalion 263, ambushes at the Chợ Gạo canal and Gò Công and destroys a Saigon Civil Guard company; sappers and engineers hit river convoys, seven craft destroyed and hundreds of tons of fuel.', '110–11', place='mekong-delta', see='cal.1969-02-22.vietnam-hanoi', check='the days; the history gives the month.', lw='The Mekong Delta in February: artillery, ambush, river convoys')
E('atlas', '1969-03-17', 'Mar. 17', 'Dầu Tiếng, Thủ Dầu Một. Twelve battalions of the American 25th and 1st Divisions, the 11th Armored Cavalry in the van, some 10,000 men, open Atlas Wedge to break the encirclement and relieve the base. Allied air and artillery drop over 1,500 tons on the Michelin plantation and villages Mar. 18–28. Eastern Nam Bộ\'s Tây Ninh–Bình Long–Biên Hòa campaign hits Trà Cao and Nước Trong: over 2,000 out of action, nine mixed companies hurt, over 200 vehicles, 20 aircraft.', '109–10', also=OP, place='dau-tieng', us=True, check='the day and the figures; the history gives its own.')
E('cambodia-bomb', '1969-03-18', 'Mar. 18', 'B-52s strike along the Cambodian border, the first bombing of Cambodia, ordered the same day. Nixon calls it the first turning point in the administration\'s conduct of the war. From March 1969 to April 1970 the B-52s fly over 3,630 sorties on Cambodia, 60 percent of those in Indochina.', '109 and n. 1; 248', th='vietnam-operations', polity='us', ntags=['name:nixon-richard-m'], names=['Nixon'], check='the order and the figures; the history gives the day and Nixon\'s judgment through Joseph A. Amter, *Lời phán quyết về Việt Nam*, a Vietnamese edition (Quân đội nhân dân, 1985), 277, and calls the raid "hoạt động bữa ăn" (Breakfast).', lw='B-52s strike along the Cambodian border')
E('montana', '1969-03', 'Mar., late', 'Route 13, Bình Long. Allied forces pull out of Trà Cao and Lộc Giang and open Montana to cut the Liberation forces\' road east and west of the Saigon River and restore the interprovincial defense line. Local forces ambush and close in; the operation fails.', '110', also=OP, us=True, at='before 1969-03-21', check='the days; the history gives "cuối tháng 3-1969".', ok=['ok:fields-place'],lw='Operation Montana in Tây Ninh and Bình Long')
E('lamson271', '1969-03-17', 'Mar. 17', 'West Quảng Trị. Group 7 of the Quảng Trị command and Regiment 8, with local forces and the people south of Hướng Hóa, defeat the Lam Sơn 271 operation, five allied battalions after the depots and corridor at Tam Tanh and A Giới.', '113 and n. 1', also=OP, place='tam-tanh', us=True, check='the end; the history prints "31-4-1969".', lw='Lam Sơn 271 defeated, west Quảng Trị')
E('april', '1969-04', 'Apr.', 'From Region 6 southward the Liberation forces fight 934 actions: a Saigon force of two battalions, three American groups, a subsector headquarters and six pacification teams hurt; over 150 aircraft shot down or destroyed, 346 vehicles, 74 river craft sunk. The 5th, 7th and 9th Divisions strike toward Route 13, Tây Ninh and Dầu Tiếng; the 5th, from Long Khánh and Định Quán, hits the Saigon 18th Division\'s headquarters.', '113–14', also=OP, us=True, check='the days; the history gives the month and its own figures.', ok=['ok:fields-place'],lw='April: 934 actions south of Region 6')
E('dongpan', '1969-05-05', 'May 5', 'Đồng Pan. Regiment 174 of the 5th Division attacks the base and hurts the battalion holding it; the rest falls back to Bầu Cỏ, Tây Ninh. The same day Regiment 141 of the 7th Division hits Tà Tê and north of Route 13 without success, the American 1st Cavalry\'s two brigades keeping the road.', '115–16', also=OP, place='dong-pan', us=True, lw='Đồng Pan attacked by Regiment 174')
E('tambung', '1969-05-08', 'May 8–9', 'Suối Tầm Bung and Route 20. Regiment 5 of the 5th Division attacks the Saigon 18th Division\'s task forces 43 and 52 and beats their sweep. The 5th Division then keeps on the 18th in Bà Rịa and Long Khánh and hurts Task Force 52 badly.', '116–17', also=OP, place='suoi-tam-bung', lw='Suối Tầm Bung: Regiment 5 beats a sweep')
E('may11-east', '1969-05-11', 'May 11', 'Eastern Nam Bộ, the summer offensive\'s first day. The 7th Division and sappers hurt the American 11th Armored Cavalry west and southwest of Hớn Quản and raid the 3d Brigade, 1st Airmobile Cavalry, at Tếch Ních; the town and Route 13 are threatened and eight airborne battalions sent up. In Tây Ninh the 9th Division hits bases around the Holy See and Vườn Điều; the strategic reserve and the American 25th\'s 1st Brigade come to relieve.', '116', also=OP, place='hon-quan', us=True, see='cal.1969-05-11.vietnam-hanoi', lw='May 11, eastern Nam Bộ: Hớn Quản, Tếch Ních, the Holy See')
E('may12', '1969-05-12', 'May 12', 'Region V, at night. Sappers and mortar teams strike the missile position at Sơn Trà, Đà Nẵng, the 1st Marine Regiment\'s headquarters at Hầm Xẻ, the 11th Brigade at Gò Hội, Quảng Ngãi, and the 5th Marine Regiment at An Hòa, Quảng Đà.', '117–18', also=OP, place='son-tra', us=True, bnd='night', words='"đêm 12-5-1969" (the night of May 12, 1969).', see='cal.1969-05-11.vietnam-hanoi', lw='May 12: sappers hit Sơn Trà, Hầm Xẻ, Gò Hội, An Hòa')
E('may19', '1969-05-19', 'May 19', 'Lòng Tàu River. For Hồ Chí Minh\'s birthday, Group 10, the Rừng Sác sappers, sink two tankers, of 7,000 and 15,000 tons, in 30 minutes. The group, cut off and encircled, feeds itself and makes its own arms.', '117', also=OP, place='long-tau-river', us=True, ntags=['name:ho-chi-minh'], names=['Hồ Chí Minh'], lw='Group 10 sinks two tankers on the Lòng Tàu')
E('may-r6', '1969-05', 'May', 'Region 6. Sappers hit the Saigon 44th Regiment at Sông Mao, Bình Thuận, a ranger camp at Lương Sơn and the subsector and gun position at Kim Ngọc. On Routes 1, 8 and 11 and north and south of Hòa Đa, the regional forces and local units stop Task Force 1/5, a Saigon mechanized infantry group: hundreds out of action.', '118', also=OP, check='the days; the history gives the month.', ok=['ok:fields-place'], lw='Region 6 in May: Sông Mao, Lương Sơn, Hòa Đa')
E('longthanh', '1969-06-15', 'June 15–16', 'Long Thành. The district\'s local forces and guerrillas hurt a battalion of the Royal Thai Black Panther Division.', '117', also=OP, place='long-thanh', tags=['polity:thailand'], lw='Long Thành forces hit a Thai battalion')
E('redeploy', '1969', '1969', 'The Supreme Command moves the 1st Division (Regiments 95C, 101C and 209) and Regiments 33, 174, 10 and 20 from the Highlands front and Region V into eastern Nam Bộ.', '93 and n. 1; 105 n. 1', also=OP, vis=True, check='the day; the history dates it to 1969 and gives the division moved from the Highlands.', lw='Supreme Command moves the 1st Division to eastern Nam Bộ')
E('north-aid', '1969', '1969', 'The North\'s support for the year: 81,090 cadres and soldiers to the South, among them artillery, engineer and signal units, 13 infantry battalions, 99 infantry companies and 35 sapper platoons; 52,424 tons of arms, supplies, food and medicine; $34,888,629. To Laos 40,200 volunteer troops, 28,701 tons and 41,300,488 Vietnamese đồng.', '93 and n. 1', also=OP+['laos'], vis=True, tocheck='*Thống kê số liệu về cuộc kháng chiến chống Mỹ, cứu nước (1954–1975)*, in the Ministry of Defense archive (cited by [[w.lich-su-khang-chien-chong-my]], VI, 93 n.).', lw='North\'s support 1969: men, tons, dollars')
dump('o1.yaml')
